  can_update boolean default false,
  can_delete boolean default false,
  created_at timestamptz default now(),
  unique(role_code, module_code)
);

-- ---------- Rider app compatibility tables ----------
create table if not exists public.merchants_2026_04_24 (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  phone text,
  address text,
  is_active boolean default true,
  created_at timestamptz default now()
);
create unique index if not exists merchants_2026_name_uidx on public.merchants_2026_04_24 (name);

create table if not exists public.townships_2026_04_24 (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  region text,
  zone_code text,
  created_at timestamptz default now()
);
create unique index if not exists townships_2026_name_uidx on public.townships_2026_04_24 (name);

create table if not exists public.tariffs_2026_04_24 (
  id uuid primary key default gen_random_uuid(),
  township_id uuid references public.townships_2026_04_24(id) on delete cascade,
  min_weight numeric(10,2) default 0,
  max_weight numeric(10,2) default 999,
  base_rate numeric(10,2) default 0,
  per_kg_rate numeric(10,2) default 0,
  created_at timestamptz default now()
);

create table if not exists public.pickups_2026_04_24 (
  id uuid primary key default gen_random_uuid(),
  pickup_id text unique not null,
  pickup_date date default current_date,
  merchant_id uuid references public.merchants_2026_04_24(id),
  pickup_township uuid references public.townships_2026_04_24(id),
  pickup_address text,
  expected_way_count int default 1,
  actual_weight numeric(10,2) default 0,
  calculated_tariff numeric(10,2) default 0,
  pickup_status text default 'DRAFT',
  remarks text,
  rider_id uuid references public.profiles(id),
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);

create table if not exists public.pickup_attachments_2026_04_24 (
  id uuid primary key default gen_random_uuid(),
  pickup_id text not null,
  attachment_type text default 'handover_photo',
  file_name text,
  file_url text,
  meta jsonb default '{}'::jsonb,
  uploaded_by uuid references public.profiles(id),
  created_at timestamptz default now()
);





-- ---------- Remove known demo/sample operational records from earlier builds ----------
do $$
  if to_regclass('public.delivery_process_events') is not null then
    delete from public.delivery_process_events
    where tracking_no like 'BX-2026-%'
       or coalesce(notes, '') ilike '%demo%';
  end if;

  if to_regclass('public.route_stops') is not null and to_regclass('public.shipments') is not null then
    if exists (
      select 1 from information_schema.columns
      where table_schema = 'public' and table_name = 'route_stops' and column_name = 'shipment_id'
    ) then
      delete from public.route_stops rs
      using public.shipments s
      where rs.shipment_id = s.id
        and (
          coalesce(s.source_file, '') ilike '%demo%'
          or s.tracking_no like 'BX-2026-%'
          or s.merchant_name in ('Golden Shop','Silver Store','Diamond Mart','Tech Store Myanmar','Fashion Hub','Book World','Home Decor Plus','Electronics Pro')
        );
    elsif exists (
      select 1 from information_schema.columns
      where table_schema = 'public' and table_name = 'route_stops' and column_name = 'tracking_no'
    ) then
      delete from public.route_stops
      where tracking_no like 'BX-2026-%';
    end if;
  end if;

  if to_regclass('public.cod_collections') is not null then
    delete from public.cod_collections
    where tracking_no like 'BX-2026-%'
       or coalesce(rider_name, '') ilike '%demo%';
  end if;

  if to_regclass('public.delivery_proofs') is not null and to_regclass('public.shipments') is not null then
    delete from public.delivery_proofs dp
    using public.shipments s
    where dp.shipment_id = s.id
      and (
        coalesce(s.source_file, '') ilike '%demo%'
        or s.tracking_no like 'BX-2026-%'
        or s.merchant_name in ('Golden Shop','Silver Store','Diamond Mart','Tech Store Myanmar','Fashion Hub','Book World','Home Decor Plus','Electronics Pro')
      );
  end if;

  if to_regclass('public.delivery_exceptions') is not null and to_regclass('public.shipments') is not null then
    delete from public.delivery_exceptions de
    using public.shipments s
    where de.shipment_id = s.id
      and (
        coalesce(s.source_file, '') ilike '%demo%'
        or s.tracking_no like 'BX-2026-%'
        or s.merchant_name in ('Golden Shop','Silver Store','Diamond Mart','Tech Store Myanmar','Fashion Hub','Book World','Home Decor Plus','Electronics Pro')
      );
  end if;

  if to_regclass('public.shipments') is not null then
    delete from public.shipments
    where coalesce(source_file, '') ilike '%demo%'
       or tracking_no like 'BX-2026-%'
       or merchant_name in ('Golden Shop','Silver Store','Diamond Mart','Tech Store Myanmar','Fashion Hub','Book World','Home Decor Plus','Electronics Pro');
  end if;

  if to_regclass('public.rider_notifications') is not null and to_regclass('public.profiles') is not null then
    delete from public.rider_notifications rn
    using public.profiles p
    where rn.user_id = p.id
      and (p.email ilike '%.demo@britiumexpress.com' or p.full_name ilike 'Demo %');
  end if;

  if to_regclass('public.profiles') is not null then
    update public.profiles
    set status = 'inactive',
        is_active = false,
        is_approved = false
    where email ilike '%.demo@britiumexpress.com'
       or full_name ilike 'Demo %';
  end if;
end $$;


-- ---------- Full demo/partial-import cleanup before reloading real workbook data ----------
-- Keeps real Supabase Auth users. Demo profile rows are only deactivated, not deleted from auth.users.
do $be_wipe_demo$
  -- Child tables that may reference shipments.
  if to_regclass('public.delivery_process_events') is not null
     and exists (select 1 from information_schema.columns where table_schema='public' and table_name='delivery_process_events' and column_name='tracking_no') then
    execute $q$
      delete from public.delivery_process_events e
      where e.tracking_no in (
        select s.tracking_no from public.shipments s
        where coalesce(s.source_file,'') = 'BE_MasterData_April.xlsx'
           or coalesce(s.source_file,'') ilike '%demo%'
           or s.tracking_no like 'BX-2026-%'
           or s.tracking_no ilike 'DEMO%'
      )
      or e.tracking_no like 'BX-2026-%'
      or e.tracking_no ilike 'DEMO%'
    $q$;
  end if;

  if to_regclass('public.route_stops') is not null and to_regclass('public.shipments') is not null then
    if exists (select 1 from information_schema.columns where table_schema='public' and table_name='route_stops' and column_name='shipment_id') then
      execute $q$
        delete from public.route_stops rs
        using public.shipments s
        where rs.shipment_id = s.id
          and (
            coalesce(s.source_file,'') = 'BE_MasterData_April.xlsx'
            or coalesce(s.source_file,'') ilike '%demo%'
            or s.tracking_no like 'BX-2026-%'
            or s.tracking_no ilike 'DEMO%'
            or s.merchant_name in ('Golden Shop','Silver Store','Diamond Mart','Tech Store Myanmar','Fashion Hub','Book World','Demo Merchant')
          )
      $q$;
    end if;
    if exists (select 1 from information_schema.columns where table_schema='public' and table_name='route_stops' and column_name='tracking_no') then
      execute $q$
        delete from public.route_stops
        where tracking_no like 'BX-2026-%'
           or tracking_no ilike 'DEMO%'
           or tracking_no in (
             select tracking_no from public.shipments
             where coalesce(source_file,'') = 'BE_MasterData_April.xlsx'
          )
      $q$;
    end if;
  end if;

  if to_regclass('public.delivery_proofs') is not null and to_regclass('public.shipments') is not null
     and exists (select 1 from information_schema.columns where table_schema='public' and table_name='delivery_proofs' and column_name='shipment_id') then
    execute $q$
      delete from public.delivery_proofs dp
      using public.shipments s
      where dp.shipment_id = s.id
        and (
          coalesce(s.source_file,'') = 'BE_MasterData_April.xlsx'
          or coalesce(s.source_file,'') ilike '%demo%'
          or s.tracking_no like 'BX-2026-%'
          or s.tracking_no ilike 'DEMO%'
          or s.merchant_name in ('Golden Shop','Silver Store','Diamond Mart','Tech Store Myanmar','Fashion Hub','Book World','Demo Merchant')
        )
    $q$;
  end if;

  if to_regclass('public.delivery_exceptions') is not null and to_regclass('public.shipments') is not null
     and exists (select 1 from information_schema.columns where table_schema='public' and table_name='delivery_exceptions' and column_name='shipment_id') then
    execute $q$
      delete from public.delivery_exceptions de
      using public.shipments s
      where de.shipment_id = s.id
        and (
          coalesce(s.source_file,'') = 'BE_MasterData_April.xlsx'
          or coalesce(s.source_file,'') ilike '%demo%'
          or s.tracking_no like 'BX-2026-%'
          or s.tracking_no ilike 'DEMO%'
          or s.merchant_name in ('Golden Shop','Silver Store','Diamond Mart','Tech Store Myanmar','Fashion Hub','Book World','Demo Merchant')
        )
    $q$;
  end if;

  if to_regclass('public.cod_collections') is not null then
    if exists (select 1 from information_schema.columns where table_schema='public' and table_name='cod_collections' and column_name='tracking_no') then
      execute $q$
        delete from public.cod_collections
        where tracking_no in (
          select tracking_no from public.shipments
          where coalesce(source_file,'') = 'BE_MasterData_April.xlsx'
             or coalesce(source_file,'') ilike '%demo%'
             or tracking_no like 'BX-2026-%'
             or tracking_no ilike 'DEMO%'
        )
        or tracking_no like 'BX-2026-%'
        or tracking_no ilike 'DEMO%'
      $q$;
    end if;
    if exists (select 1 from information_schema.columns where table_schema='public' and table_name='cod_collections' and column_name='rider_name') then
      execute $q$ delete from public.cod_collections where coalesce(rider_name,'') ilike '%demo%' $q$;
    end if;
  end if;

  -- Rider-app pickup compatibility tables.
  if to_regclass('public.pickup_attachments_2026_04_24') is not null
     and exists (select 1 from information_schema.columns where table_schema='public' and table_name='pickup_attachments_2026_04_24' and column_name='pickup_id') then
    execute $q$
      delete from public.pickup_attachments_2026_04_24
      where pickup_id like 'PU-%'
         or pickup_id ilike '%demo%'
    $q$;
  end if;

  if to_regclass('public.pickups_2026_04_24') is not null then
    if exists (select 1 from information_schema.columns where table_schema='public' and table_name='pickups_2026_04_24' and column_name='pickup_id') then
      execute $q$
        delete from public.pickups_2026_04_24
        where pickup_id like 'PU-%'
           or pickup_id ilike '%demo%'
      $q$;
    end if;
    if exists (select 1 from information_schema.columns where table_schema='public' and table_name='pickups_2026_04_24' and column_name='remarks') then
      execute $q$
        delete from public.pickups_2026_04_24
        where coalesce(remarks,'') ilike '%demo%'
           or coalesce(remarks,'') ilike '%BE_MasterData_April.xlsx%'
      $q$;
    end if;
  end if;

  -- Main operational rows: remove previous partial BE import and all known demo shipments/pickups.
  if to_regclass('public.shipments') is not null then
    execute $q$
      delete from public.shipments
      where coalesce(source_file,'') = 'BE_MasterData_April.xlsx'
         or coalesce(source_file,'') ilike '%demo%'
         or tracking_no like 'BX-2026-%'
         or tracking_no ilike 'DEMO%'
         or merchant_name in ('Golden Shop','Silver Store','Diamond Mart','Tech Store Myanmar','Fashion Hub','Book World','Demo Merchant')
    $q$;
  end if;

  if to_regclass('public.pickups') is not null then
    execute $q$
      delete from public.pickups
      where coalesce(source_file,'') = 'BE_MasterData_April.xlsx'
         or coalesce(source_file,'') ilike '%demo%'
         or pickup_code like 'PU-DEMO%'
         or merchant_name in ('Golden Shop','Silver Store','Diamond Mart','Tech Store Myanmar','Fashion Hub','Book World','Demo Merchant')
    $q$;
  end if;

  -- Master demo rows.
  if to_regclass('public.merchants') is not null then
    execute $q$
      delete from public.merchants
      where coalesce(name,'') ilike '%demo%'
         or name in ('Golden Shop','Silver Store','Diamond Mart','Tech Store Myanmar','Fashion Hub','Book World','Demo Merchant')
    $q$;
  end if;

  if to_regclass('public.merchants_2026_04_24') is not null then
    execute $q$
      delete from public.merchants_2026_04_24
      where coalesce(name,'') ilike '%demo%'
         or name in ('Golden Shop','Silver Store','Diamond Mart','Tech Store Myanmar','Fashion Hub','Book World','Demo Merchant')
    $q$;
  end if;

  if to_regclass('public.staff_master') is not null then
    execute $q$
      delete from public.staff_master
      where coalesce(email,'') ilike '%demo%'
         or coalesce(email,'') ilike '%.demo@britiumexpress.com'
         or coalesce(name,'') ilike 'Demo %'
         or coalesce(name,'') ilike '% demo'
    $q$;
  end if;

  if to_regclass('public.rider_notifications') is not null and to_regclass('public.profiles') is not null
     and exists (select 1 from information_schema.columns where table_schema='public' and table_name='rider_notifications' and column_name='user_id') then
    execute $q$
      delete from public.rider_notifications rn
      using public.profiles p
      where rn.user_id = p.id
        and (p.email ilike '%.demo@britiumexpress.com' or p.email ilike '%demo%' or p.full_name ilike 'Demo %')
    $q$;
  end if;

  if to_regclass('public.profiles') is not null then
    execute $q$
      update public.profiles
         set status = 'inactive',
             is_active = false,
             is_approved = false
       where email ilike '%.demo@britiumexpress.com'
          or email ilike '%demo%'
          or full_name ilike 'Demo %'
    $q$;
  end if;
end
$be_wipe_demo$;


