-- Default tariffs from township delivery charges.
insert into public.tariffs_2026_04_24 (township_id, min_weight, max_weight, base_rate, per_kg_rate)
select t.id, 0, 5, coalesce(tm.delivery_charge, 0), 0
from public.townships_2026_04_24 t
left join public.townships tm on tm.name = t.name
on conflict do nothing;


